        k = int(ty[8:]); w = w[:max(0, len(w) - k)]
    elif ty == 'UppercaseFirst':
        if w: _upper(w, 0)
    elif ty == 'UppercaseAll':
        i = 0
        while i < len(w): i += _upper(w, i)
    return pre.encode('latin1') + bytes(w) + suf.encode('latin1')

def lit_ctx(mode, p1, p2):
    if mode == 0: return p1 & 0x3f
    if mode == 1: return p1 >> 2
    if mode == 2: return LUT0[p1] | LUT1[p2]
    return (LUT2[p1] << 3) | LUT2[p2]

def bl_code(count):
    for i in range(25, -1, -1):
        if BL_BASE[i] <= count:
            assert count - BL_BASE[i] < (1 << BL_EXTRA[i]), count
            return i, count - BL_BASE[i]

class State:
    """decoder-side state carried across meta-blocks"""
    def __init__(self, wbits_=22):
        self.wbits = wbits_
        self.out = bytearray()
        self.rb = [4, 11, 15, 16]  # rb[0] = last distance

    def max_dist(self):
        return min(len(self.out), (1 << self.wbits) - 16)

    def dist_from_code(self, dcode, extra, npostfix, ndirect):
        rb = self.rb
        if dcode < 16:
            tab = [(0, 0), (1, 0), (2, 0), (3, 0), (0, -1), (0, 1), (0, -2), (0, 2), (0, -3), (0, 3),
                   (1, -1), (1, 1), (1, -2), (1, 2), (1, -3), (1, 3)]
            i, d = tab[dcode]
            return rb[i] + d
        if dcode < 16 + ndirect:
            return dcode - 15
        x = dcode - ndirect - 16
        nb = 1 + (x >> (npostfix + 1))
        hcode = x >> npostfix
        lcode = x & ((1 << npostfix) - 1)
        off = ((2 + (hcode & 1)) << nb) - 4
        return ((off + extra) << npostfix) + lcode + ndirect + 1

    def find_dcode(self, d, npostfix, ndirect, allow_short=True):
        if allow_short:
            for c in range(16):
                if self.dist_from_code(c, 0, npostfix, ndirect) == d:
                    return c, 0, 0
        c, nb, e = dist_sym(d, npostfix, ndirect)
        return c, nb, e

class Cat:
    def __init__(self, nbl, blocks):
        self.nbl = nbl
        self.blocks = list(blocks) if blocks else [(0, 1 << 24)]
        self.bi = 0
        self.btype = self.blocks[0][0]
        self.left = self.blocks[0][1]
        self.rb = [1, 0]  # second-to-last, last

    def btype_sym(self, new, override=None):
        if override is not None: return override
        if new == self.rb[0]: return 0
        if new == (self.rb[1] + 1) % self.nbl: return 1
        return new + 2

class Emitter:
    def __init__(self, bw=None):
        self.bw = bw
        self.freq = defaultdict(Counter)
        self.codes = {}
    def sym(self, key, s):
        if self.bw is None: self.freq[key][s] += 1
        else:
            c = self.codes[key]
            if s not in c.lens: raise ValueError('symbol %r not in code %r' % (s, key))
            c.put(self.bw, s)
    def bits(self, v, n):
        if self.bw is not None: self.bw.put(v, n)

def cmap_symbols(cmap, rlemax, imtf):
    vals = list(cmap)
    if imtf:
        mtf = list(range(256)); v2 = []
        for v in vals:
            i = mtf.index(v); v2.append(i); mtf.pop(i); mtf.insert(0, v)
        vals = v2
    syms = []  # (sym, extra, nbits)
    i = 0
    while i < len(vals):
        if vals[i] == 0 and rlemax:
            j = i
            while j < len(vals) and vals[j] == 0: j += 1
            run = j - i
            while run > 0:
                if run == 1:
                    syms.append((0, 0, 0)); run -= 1; continue
                k = min(run.bit_length() - 1, rlemax)
                take = min(run, (1 << (k + 1)) - 1)
                syms.append((k, take - (1 << k), k)); run -= take
            i = j; continue
        v = vals[i]
        syms.append((v + rlemax if v else 0, 0, 0)); i += 1
    return syms

def write_cmap(bw, ntrees, cmap, rlemax=0, imtf=False, spec=None, symbols=None):
    varlen8(bw, ntrees - 1)
    if ntrees < 2: return
    if rlemax: bw.put(1, 1); bw.put(rlemax - 1, 4)
    else: bw.put(0, 1)
    syms = symbols if symbols is not None else cmap_symbols(cmap, rlemax, imtf)
    asize = ntrees + rlemax
    code = write_spec(bw, asize, spec, Counter(s for s, _, _ in syms))
    for s, e, nb in syms:
        code.put(bw, s); bw.put(e, nb)
    bw.put(1 if imtf else 0, 1)

def write_spec(bw, asize, spec, freq):
    """spec: None (auto) | ('simple', syms, ts) | ('complex', lens_dict_or_list, kwargs) | callable(bw, asize, freq)->PCode"""
    if spec is None:
        if not freq: freq = Counter({0: 1})
        return write_code_auto(bw, asize, freq)
    if callable(spec): return spec(bw, asize, freq)
    if spec[0] == 'simple':
        return write_simple(bw, asize, list(spec[1]), spec[2] if len(spec) > 2 else 0)
    if spec[0] == 'complex':
        lens = spec[1]
        if isinstance(lens, dict):
            l2 = [0] * asize
            for s, l in lens.items(): l2[s] = l
            lens = l2
        kw = spec[2] if len(spec) > 2 else {}
        return write_complex(bw, asize, lens, **kw)
    if spec[0] == 'complex_auto':
        kw = spec[1] if len(spec) > 1 else {}
        return write_code_auto(bw, asize, freq, force_complex=True, **kw)
    raise ValueError(spec)

def compressed_mb(bw, st, mlen, cmds, islast=False, nibbles=None, nbl=(1, 1, 1), blocks=(None, None, None),
                  npostfix=0, ndirect=0, cmodes=None, ntreesl=1, cmapl=None, cmapl_opts=None,
                  ntreesd=1, cmapd=None, cmapd_opts=None, specs=None, btype_specs=None, bcount_specs=None,
                  stop_after_header=False, check=True):
    """cmds: list of dict(ins=bytes, copy=int, dist=None(implicit '0') | int distance | ('code', dcode, extra),
                          sym=override cmd symbol, ins_extra/copy_extra override)
       blocks[c]: list of (type, count[, sym_override]) ; first block type must be 0."""
    cmodes = list(cmodes) if cmodes is not None else [0] * nbl[0]
    cmapl = list(cmapl) if cmapl is not None else [0] * (64 * nbl[0])
    cmapd = list(cmapd) if cmapd is not None else [0] * (4 * nbl[2])
    specs = specs or {}
    btype_specs = btype_specs or {}
    bcount_specs = bcount_specs or {}
    dalpha = dist_alpha(npostfix, ndirect)
    save = (bytearray(st.out), list(st.rb))

    def run(em):
        st.out[:] = save[0]; st.rb[:] = save[1]
        cats = [Cat(nbl[i], blocks[i] if nbl[i] > 1 else None) for i in range(3)]
        start = len(st.out)
        def tick(ci):
            c = cats[ci]
            if c.left == 0:
                c.bi += 1
                b = c.blocks[c.bi]
                new, cnt = b[0], b[1]
                s = c.btype_sym(new, b[2] if len(b) > 2 else None)
                em.sym(('bt', ci), s)
                i, e = bl_code(cnt)
                em.sym(('bc', ci), i); em.bits(e, BL_EXTRA[i])
                c.rb = [c.rb[1], new]
                c.btype = new; c.left = cnt
            c.left -= 1
        for cmd in cmds:
            ins = cmd.get('ins', b''); cp = cmd.get('copy', 4); dist = cmd.get('dist', None)
            tick(1)
            ic, ie = ins_code(len(ins)); cc, ce = copy_code(cp)
            implicit = dist is None
            s = cmd.get('sym')
            if s is None:
                s = cmd_sym(ic, cc, False) if implicit else None
                if s is None: s = cmd_sym(ic, cc, True); implicit = False if dist is not None else implicit
            em.sym(('cmd', cats[1].btype), s)
            em.bits(cmd.get('ins_extra', ie), INS_EXTRA[ic]); em.bits(cmd.get('copy_extra', ce), COPY_EXTRA[cc])
            for x in ins:
                tick(0)
                p1 = st.out[-1] if len(st.out) >= 1 else 0
                p2 = st.out[-2] if len(st.out) >= 2 else 0
                ctx = lit_ctx(cmodes[cats[0].btype], p1, p2)
                tree = cmapl[64 * cats[0].btype + ctx]
                em.sym(('lit', tree), x)
                st.out.append(x)
            if len(st.out) - start >= mlen and check:
                break
            if dist is None or (s < 128):
                dcode = 0; d = st.rb[0]
            else:
                tick(2)
                dctx = 3 if cp > 4 else cp - 2
                tree = cmapd[4 * cats[2].btype + dctx]
                if isinstance(dist, tuple) and dist[0] == 'code':
                    dcode, dext = dist[1], dist[2]
                    nb = 0
                    if dcode >= 16 + ndirect:
                        nb = 1 + ((dcode - ndirect - 16) >> (npostfix + 1))
                else:
                    dcode, nb, dext = st.find_dcode(dist, npostfix, ndirect, cmd.get('short', True))
                em.sym(('dist', tree), dcode); em.bits(dext, nb)
                d = st.dist_from_code(dcode, dext, npostfix, ndirect)
            md = st.max_dist()
            if d > md:
                if not (4 <= cp <= 24):
                    if check: raise ValueError('bad dict copy len')
                    break
                wid = d - md - 1
                idx = wid & ((1 << NDBITS[cp]) - 1); t = wid >> NDBITS[cp]
                if t >= 121:
                    if check: raise ValueError('bad transform')
                    break
                st.out += transform(dict_word(cp, idx), t)
            else:
                if d <= 0:
                    if check: raise ValueError('bad distance')
                    break
                for _ in range(cp): st.out.append(st.out[-d])
                if dcode != 0: st.rb = [d] + st.rb[:3]
        if check and len(st.out) - start != mlen:
            raise ValueError('mlen mismatch: produced %d, mlen %d' % (len(st.out) - start, mlen))

    # pass 1: frequencies
    em = Emitter(None)
    # include initial block counts
    for ci in range(3):
        if nbl[ci] > 1:
            i, e = bl_code(blocks[ci][0][1]); em.freq[('bc', ci)][i] += 1
    run(em)
    freq = em.freq
    # header
    em.bw = bw
    mb_header(bw, mlen, islast=islast, nibbles=nibbles)
    for ci in range(3):
        varlen8(bw, nbl[ci] - 1)
        if nbl[ci] > 1:
            em.codes[('bt', ci)] = write_spec(bw, nbl[ci] + 2, btype_specs.get(ci), freq[('bt', ci)] or Counter({0: 1}))
            em.codes[('bc', ci)] = write_spec(bw, 26, bcount_specs.get(ci), freq[('bc', ci)])
            i, e = bl_code(blocks[ci][0][1])
            em.codes[('bc', ci)].put(bw, i); bw.put(e, BL_EXTRA[i])
    bw.put(npostfix, 2); bw.put(ndirect >> npostfix, 4)
    for m in cmodes: bw.put(m, 2)
    write_cmap(bw, ntreesl, cmapl, **(cmapl_opts or {}))
    write_cmap(bw, ntreesd, cmapd, **(cmapd_opts or {}))
    for t in range(ntreesl):
        em.codes[('lit', t)] = write_spec(bw, 256, specs.get(('lit', t)), freq[('lit', t)])
    for t in range(nbl[1]):
        em.codes[('cmd', t)] = write_spec(bw, 704, specs.get(('cmd', t)), freq[('cmd', t)])
    for t in range(ntreesd):
        em.codes[('dist', t)] = write_spec(bw, dalpha, specs.get(('dist', t)), freq[('dist', t)])
    if stop_after_header:
        return em
    run(em)
    return em

def new_stream(w=22):
    bw = BW(); wbits(bw, w); st = State(w)
    return bw, st

def uncompressed_st(bw, st, data, pad=0):
    uncompressed(bw, data, pad=pad); st.out += data

