        vals = vals[:last + 1]
    else:
        vals = vals[:n]
    return vals
def complex_raw(hskip, cl_d, seq, lens_result, cl_n=None):
    """returns code_writer: writes complex code with explicit cl lengths dict and explicit symbol sequence"""
    def w(bw):
        vals = cl_vals_for(hskip, cl_d, cl_n)
        cl_raw(bw, hskip, vals)
        nz = [s for s in cl_d if cl_d[s]]
        clc = PCode({nz[0]: 0}) if len(nz) == 1 else PCode(cl_d)
        for s, e in seq:
            clc.put(bw, s)
            if s == 16: bw.put(e, 2)
            elif s == 17: bw.put(e, 3)
        return PCode(lens_result)
    return w
